export const TAILWIND_TEMPLATE = "/*\n * Optional Tailwind CSS v4 bridge for NeuralNg primitive color tokens.\n * Import this file from a Tailwind-processed stylesheet after `tailwindcss`.\n */\n@theme inline {\n  --color-primary-50: var(--neural-color-primary-50);\n  --color-primary-100: var(--neural-color-primary-100);\n  --color-primary-200: var(--neural-color-primary-200);\n  --color-primary-300: var(--neural-color-primary-300);\n  --color-primary-400: var(--neural-color-primary-400);\n  --color-primary-500: var(--neural-color-primary-500);\n  --color-primary-600: var(--neural-color-primary-600);\n  --color-primary-700: var(--neural-color-primary-700);\n  --color-primary-800: var(--neural-color-primary-800);\n  --color-primary-900: var(--neural-color-primary-900);\n  --color-primary-950: var(--neural-color-primary-950);\n\n  --color-surface-0: var(--neural-color-surface-0);\n  --color-surface-50: var(--neural-color-surface-50);\n  --color-surface-100: var(--neural-color-surface-100);\n  --color-surface-200: var(--neural-color-surface-200);\n  --color-surface-300: var(--neural-color-surface-300);\n  --color-surface-400: var(--neural-color-surface-400);\n  --color-surface-500: var(--neural-color-surface-500);\n  --color-surface-600: var(--neural-color-surface-600);\n  --color-surface-700: var(--neural-color-surface-700);\n  --color-surface-800: var(--neural-color-surface-800);\n  --color-surface-900: var(--neural-color-surface-900);\n  --color-surface-950: var(--neural-color-surface-950);\n}\n\n/*\n * Tailwind Preflight applies `font: inherit` to native controls. Re-apply the\n * Button typography in the components layer so Preflight cannot inflate the\n * control, while Tailwind utilities still retain final ownership.\n */\n@layer components {\n  .neural-btn-base {\n    font-family: var(--neural-button-font-family, inherit);\n    font-size: var(--neural-button-font-size, 0.875rem);\n    line-height: var(--neural-button-line-height, 1.25);\n  }\n\n  .neural-btn-small-base {\n    font-size: var(--neural-button-small-font-size, 0.8125rem);\n  }\n\n  .neural-btn-large-base {\n    font-size: var(--neural-button-large-font-size, 1rem);\n  }\n}\n";
